<?php
require_once "auth.php";require_once "database.php";$page_title="Quotations";$search=trim($_GET['q']??'');$like="%$search%";
$st=$conn->prepare("SELECT q.*,c.name customer FROM quotations q LEFT JOIN customers c ON q.customer_id=c.id WHERE q.quotation_no LIKE ? OR c.name LIKE ? ORDER BY q.id DESC");$st->bind_param("ss",$like,$like);$st->execute();$rows=$st->get_result();
include "header.php";?><div style="display:flex;justify-content:space-between"><div><h1 class="page-title">Quotations</h1><p class="muted">Quotation history and records.</p></div><a class="btn primary" href="quotation_create.php">+ New Quotation</a></div>
<div class="card"><form class="searchbar"><input name="q" value="<?=htmlspecialchars($search)?>" placeholder="Search quotation or customer"><button class="btn light">Search</button></form><div class="table-wrap"><table class="table"><tr><th>Quotation</th><th>Customer</th><th>Project</th><th>Date</th><th class="right">Total</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['quotation_no']?></td><td><?=htmlspecialchars($r['customer']??'Walk-in')?></td><td><?=htmlspecialchars($r['project'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td class="right"><?=number_format($r['total'])?> MMK</td><td><a class="btn light" href="quotation_view.php?id=<?=$r['id']?>">View</a> <a class="btn danger" href="quotation_delete.php?id=<?=$r['id']?>" onclick="return confirm('Delete quotation?')">Delete</a></td></tr><?php endwhile;?></table></div></div><?php include "footer.php";?>